use std::io::{self, BufRead};

fn main() {
    let mut converted = 0;
    for line in io::stdin().lock().lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        let value = match (parts.len(), parts[0].parse::<f64>()) {
            (2, Ok(v)) => v,
            _ => {
                println!("Cannot read: {line}");
                continue;
            }
        };
        let celsius = match parts[1].to_uppercase().as_str() {
            "C" => value,
            "F" => (value - 32.0) * 5.0 / 9.0,
            "K" => value - 273.15,
            _ => {
                println!("Unknown unit in: {line}");
                continue;
            }
        };
        if celsius < -273.15 {
            println!("Below absolute zero: {line}");
            continue;
        }
        let fahrenheit = celsius * 9.0 / 5.0 + 32.0;
        let kelvin = celsius + 273.15;
        println!("{celsius:.2} C = {fahrenheit:.2} F = {kelvin:.2} K");
        converted += 1;
    }
    println!("Converted {converted} values");
}
